<?php
declare(strict_types=1);namespace App\Controllers;use App\Exceptions\NotFoundException;use App\Support\{Request,Response};
final class AdminKycController extends Controller {public function index(Request $r):Response{$rows=app('database')?->select('SELECT k.*,u.email,c.name country_name FROM kyc_submissions k JOIN users u ON u.id=k.user_id JOIN countries c ON c.id=k.country_id ORDER BY k.created_at DESC LIMIT 100')??[];return $this->view('admin/kyc',['title'=>'KYC queue','submissions'=>$rows],'layouts.admin');}public function config(Request $r):Response{$countries=app('countries')->all();$configs=app('database')?->select('SELECT * FROM kyc_configurations WHERE is_active=1')??[];$forms=app('database')?->select('SELECT * FROM dynamic_forms WHERE purpose="KYC" AND active=1')??[];return $this->view('admin/kyc-config',['title'=>'KYC configuration','countries'=>$countries,'configs'=>$configs,'forms'=>$forms],'layouts.admin');}public function saveConfig(Request $r):Response{try{$db=app('database');$country=(int)$r->input('country_id');$old=$db?->one('SELECT MAX(version) version FROM kyc_configurations WHERE country_id=?',[$country]);$db?->execute('UPDATE kyc_configurations SET is_active=0 WHERE country_id=?',[$country]);$db?->execute('INSERT INTO kyc_configurations(country_id,form_id,is_required,instructions,version,is_active) VALUES (?,?,?,?,?,1)',[$country,$r->input('form_id')?:null,$r->input('is_required')?1:0,(string)$r->input('instructions'),((int)($old['version']??0))+1]);$this->flash('success','Country KYC configuration saved as a new version.');}catch(\Throwable $e){$this->flash('error',$e->getMessage());}return $this->redirect('admin.kyc.config');}public function show(Request $r):Response{$s=app('database')?->one('SELECT k.*,u.email,c.name country_name FROM kyc_submissions k JOIN users u ON u.id=k.user_id JOIN countries c ON c.id=k.country_id WHERE k.id=?',[(int)$r->route('kyc')]);if(!$s)throw new NotFoundException('KYC submission not found.');$db=app('database');return $this->view('admin/kyc-detail',['title'=>'KYC '.$s['public_id'],'submission'=>$s,'values'=>$db?->select('SELECT * FROM kyc_submission_values WHERE kyc_submission_id=?',[$s['id']])??[],'documents'=>app('kyc')->documents((int)$s['id'])],'layouts.admin');}public function document(Request $r):Response{$doc=app('database')?->one('SELECT d.*,d.kyc_submission_id FROM kyc_documents d WHERE d.id=? AND d.kyc_submission_id=?',[(int)$r->route('document'),(int)$r->route('kyc')]);if(!$doc)throw new NotFoundException('Document not found.');return app(MediaController::class)->privateFile((string)$doc['storage_path'],(string)$doc['original_filename'],(string)$doc['mime_type'],(bool)$r->input('download'));}public function action(Request $r):Response{try{app('kyc')->review((int)$r->route('kyc'),(int)$_SESSION['user_id'],(string)$r->input('action'),(string)$r->input('message'),(string)$r->input('private_note'));$this->flash('success','KYC updated.');}catch(\Throwable $e){$this->flash('error',$e->getMessage());}return $this->redirect('admin.kyc.show',['kyc'=>(int)$r->route('kyc')]);}}
